int currentLimit = round(inverter->SystemConfigPara()->getLimitPercent() * inverter->DevInfo()->getMaxPower() / 100.0);
auto currentDiff = std::abs(effPowerLimit - currentLimit );

if (diff < hysteresis && currentDiff < hysteresis ){
